"""Write a reviewed, bounded exposure-probe report and threshold-specific figures."""
from pathlib import Path
import argparse,json,hashlib,sys
import numpy as np,pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from evaluate_controlled_exposure import fit


def dump(p,x):p.write_text(json.dumps(x,indent=2)+'\n')
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()

def run(root,out):
    m=pd.read_csv(out/'manifest.csv').fillna('');r=pd.read_csv(out/'metrics.csv');s=pd.read_csv(out/'specificity.csv');h=pd.read_csv(out/'hard_negative_metrics.csv');hs=pd.read_csv(out/'hard_negative_specificity.csv');d=np.load(out/'inputs.npz')
    # Regression check for the numerical failure actually observed in the original baseline.
    ob=d['observed'].all(0);x=d['x'][:,ob].astype(float);genes=d['genes'][ob];y=m.radiation_label.to_numpy(int)
    tr=np.flatnonzero((m.cell_type=='IMR90')&(m.group=='normal')&(m.source_file!='BFX17_expr.txt'))
    te=np.flatnonzero(m.training_eligible&(m.source_file=='BFX17_expr.txt'));model=fit('expression_linear',x[tr],y[tr]);j=int(np.flatnonzero(genes=='TAS1R2')[0]);assert not model.named_steps['variance'].get_support()[j]
    changed=x[te].copy();changed[:,j]=1e6;assert np.array_equal(model.decision_function(changed),model.decision_function(x[te]))
    # Validate all held-out blocks and metadata-label consistency independently from the evaluator.
    pred=pd.read_csv(out/'predictions.csv');split=pd.read_csv(out/'splits.csv');metadata=m.set_index('id')
    for key,g in split.groupby(['model','evaluation','fold']):
        trids=g[g.role=='train'].id;teids=g[g.role=='test'].id;assert not set(trids)&set(teids)
        if key[1]=='held_out_expression_file':assert not set(metadata.loc[trids].source_file)&set(metadata.loc[teids].source_file)
    assert not pred.duplicated(['model','evaluation','fold','id']).any()
    assert np.isfinite(pred.score_logit).all()
    # Review output: AUROC and threshold errors are separate, avoiding high-AUROC overclaims.
    fig,axs=plt.subplots(1,2,figsize=(13,4.8),constrained_layout=True)
    st=['bleomycin','antimycin','oligomycin','rotenone'];base=s[s.model=='bridge_meanstd_linear'].set_index('stress');adapt=hs[hs.model=='bridge_meanstd_linear'].set_index('condition')
    idx=np.arange(4)
    axs[0].bar(idx-.18,[base.loc[k].stress_false_positive_fraction for k in st],.36,color='#167d8d',label='IR vs control training')
    axs[0].bar(idx+.18,[adapt.loc[k].positive_fraction for k in st],.36,color='#d08636',label='Add other stresses as negatives')
    axs[0].set_xticks(idx,st,rotation=15);axs[0].set_ylabel('Fraction called radiation-positive');axs[0].set_title('Held-out non-radiation challenges');axs[0].legend(fontsize=8);axs[0].set_ylim(0,1.08)
    b=r[(r.model=='bridge_meanstd_linear')&(r.evaluation=='external_lung_chip')].set_index('fold');a=h[(h.model=='bridge_meanstd_linear')&(h.evaluation=='external_lung_chip')].set_index('fold');folds=list(b.index)
    axs[1].bar(idx-.18,b.balanced_accuracy,.36,color='#167d8d',label='IR vs control training');axs[1].bar(idx+.18,a.loc[folds].balanced_accuracy,.36,color='#d08636',label='Add other stresses as negatives');axs[1].set_xticks(idx,[v.replace('Lung ','').replace('_','\n') for v in folds]);axs[1].axhline(.5,color='#666',ls='--');axs[1].set_ylim(0,1.08);axs[1].set_ylabel('Balanced accuracy, fixed zero-logit threshold');axs[1].set_title('Independent lung-chip study')
    for ax in axs:ax.spines[['top','right']].set_visible(False);ax.grid(axis='y',alpha=.15)
    fig.suptitle('Specificity improved for one stress, but did not generalize\nAdding negatives is an adaptive development comparison; these are small culture experiments.',fontsize=11)
    fig.savefig(out/'specificity_and_transfer.pdf');fig.savefig(out/'specificity_and_transfer.png',dpi=180);plt.close(fig)
    audit=[
     {'study':'GSE230181','use':'executed','profiles':91,'design':'10 Gy / 14-day irradiated cultures plus matched controls and other senescence-inducing treatments','domain':'IMR90 and four other non-transformed human cell types','limits':'Culture replicates, one IMR90 strain; high-dose late response; senescence and exposure identity not separable from IR/control alone','source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE230181'},
     {'study':'GSE242706','use':'external test executed','profiles':32,'design':'16 Gy versus sham, 6 hours / 7 days; epithelium and endothelium','domain':'Human alveolus-on-chip','limits':'Different dose/time/tissue; channels/replicates may share chips; two cell-line metadata inconsistencies retained','source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE242706'},
     {'study':'GSE222998','use':'audited; excluded from model input pending quantification audit','profiles':16,'design':'8 human ISS RNA-seq samples (2 per gravity/time cell), plus 8 human analog/laminin samples (some treatments n=1)','domain':'HEK293; other species and ribosome profiling excluded from candidate count','limits':'Published counts are CDS/transcript-level; first file 227264 transcript rows, 100283 with lengths. Summing would risk isoform double counting. NCBI gene-count endpoint returned 404. Requires dedicated conversion/requantification.','source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE222998'},
     {'study':'GSE224805','use':'previously explored context; no new independent claim','profiles':6,'design':'Microgravity versus onboard 1g','domain':'MG63 osteosarcoma-derived cells','limits':'Different cell domain; previously used in development','source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE224805'},
     {'study':'GSE157937','use':'previously explored context; no new independent claim','profiles':8,'design':'Microgravity, onboard 1g and Earth','domain':'HMEC-1 endothelial cells','limits':'Only two onboard controls; known pretraining catalog overlap','source':'https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE157937'},
    ];pd.DataFrame(audit).to_csv(out/'dataset_audit.csv',index=False)
    er=json.loads((out/'inference_report.json').read_text());v=json.loads((out/'verification.json').read_text());v.update({'near_constant_gene_invariance_check':True,'independently_checked_split_ID_disjointness':True,'no_duplicate_prediction_rows':True,'finite_score_max_absolute':float(abs(pred.score_logit).max()),'inference_script_hash_matches':sha(root/'workstreams/spaceflight/scripts/controlled_exposure_pilot.py')==er['script_sha256']});assert v['inference_script_hash_matches'];dump(out/'verification.json',v)
    lines=['# Controlled-exposure validation — September 14, 2026','', '**Verdict: BRIDGE supports a useful irradiation-associated probe in one cell context, but the current probe is not specific or transferable enough to label a flight sample “radiation-driven.”** The six broad pathway averages are also insufficient as a reliable exposure bottleneck.','', '[Specificity/transfer figure](specificity_and_transfer.pdf) · [All-model AUROC figure](exposure_probe_validation.pdf) · [Dataset audit](dataset_audit.csv)','', '## What ran','', 'Downloaded and audited **123 new public profiles**: 91 from GSE230181 and 32 from GSE242706. Prepared 15,061 common observed canonical genes with audited sample labels and columns. Frozen BRIDGE inference ran on moe-reboot’s A100 in **45.5 seconds**. Small local logistic heads were then fitted; no encoder update occurred.','', 'The initial radiation-associated head used **38 normal IMR90 cultures** (19 irradiated, 19 controls) from five named experiment sets spanning four expression files. Entire files were held out; the B/C sets stayed together. Other cell types were secondary within-study tests; the lung-chip study supplied a separate external test. These are culture replicates, not 123 donors.','', 'Four fixed comparisons used expression, PCA (5 components), BRIDGE mean+SD, and the same six predefined response-program averages. No layer/LoRA search, sign reversal, threshold tuning or calibration was performed.','', '## 1. Within-study recognition is strong, but not unique to BRIDGE','', 'Across all four held-out files, BRIDGE, expression and PCA each achieved **AUROC 1.0 and balanced accuracy 1.0** for irradiated versus control IMR90 cultures. Thus this task provides no clear predictive advantage for BRIDGE. The six-program head varied substantially: AUROC **0.22–1.0**, balanced accuracy **0.25–0.83**. A small set of generic pathway averages does not reliably summarize the exposure decision.','', '## 2. Non-radiation stresses expose a specificity problem','', 'The BRIDGE probe ranked irradiated cultures above bleomycin, antimycin, oligomycin and rotenone cultures in the matched held-out-file comparisons (AUROC 1.0). However, a high ranking score does not make its binary decisions specific:','', '| Non-radiation treatment | Positive calls, initial BRIDGE probe | Matched controls positive |','|---|---:|---:|']
    for k,n in [('bleomycin',5),('antimycin',5),('oligomycin',5),('rotenone',3),('ras_induction',3)]:
        q=base.loc[k];lines.append(f'| {k} | {round(q.stress_false_positive_fraction*n)}/{n} | {round(q.control_false_positive_fraction*q.n_control)}/{int(q.n_control)} |')
    lines+=['','Ras is a separate hTERT/inducible-genotype context, and its file has no irradiated comparison. It is a secondary specificity challenge. Treatments, timing, and culture protocols differ; these tests do not isolate a single common mechanism.','', '## 3. Independent-study transfer depends on cell type and time','', '| External lung-chip stratum | BRIDGE AUROC | Balanced accuracy | TP / TN / FP / FN |','|---|---:|---:|---|']
    for fold,q in b.iterrows():lines.append(f'| {fold} | {q.auroc:.3f} | {q.balanced_accuracy:.3f} | {int(q.TP)} / {int(q.TN)} / {int(q.FP)} / {int(q.FN)} |')
    lines+=['','Each row has four irradiated and four sham profiles. Do not pool channels and time points as independent donors. Expression and PCA achieved AUROC 0.69–1.0 but balanced accuracy 0.5 in every stratum, illustrating strong score-offset/domain effects. The one perfect BRIDGE stratum is encouraging development evidence, not broad validation.','', '## 4. A bounded correction helps one challenge but hurts transfer','', 'After seeing the false positives, one **explicitly adaptive** comparison added verified non-IR normal-IMR90 treatments and vehicle controls as training negatives. The full development set became 61 cultures; entire-file holdouts remained intact. Ras/hTERT samples were excluded. The same model settings and threshold were retained.','', 'BRIDGE bleomycin false positives fell from **4/5 to 1/5**, with **5/5 irradiated** cultures still positive in that held-out file. Rotenone remained **3/3 false positives**, and **2/3 controls** in its file became positive. External lung-chip balanced accuracy became **0.5 in every stratum**, with all samples called positive; AUROC ranged **0.25–0.81**. This version is not promoted as a generally improved detector. The exposure label needs more varied, matched examples rather than an outcome-selected threshold.','', 'The adaptive comparison used already inspected evaluation data; its apparent local improvement needs independent confirmation. See `hard_negative_amendment.json` and `hard_negative_metrics.csv`.','', '## 5. Connection to the existing flight classifier','', 'As an explicitly out-of-domain diagnostic, the two unchanged muscle-chip flight heads were applied to the controlled-exposure embeddings. Radiation lowered the old flight score in **all five IMR90 experiment sets under both heads**. This does not prove radiation can never contribute in muscle; tissue, dose, timing and preparation differ. It does show that the current flight head cannot simply be relabeled as a radiation detector. No radiation percentage is assigned to a flight sample. The prior failed cross-flight result is unchanged.','', '## Gravity data audit and next step','', 'GSE222998 is a relevant new candidate with eight human HEK293 ISS RNA-seq profiles comparing microgravity and centrifuged 1g at 24/48 hours, plus human ground analog experiments. The author files contain transcript/CDS counts across many isoforms, rather than gene-level counts compatible with the current preprocessing contract. The NCBI processed gene-count route was unavailable (404). It was audited but not fed into BRIDGE by summing potentially overlapping transcript counts. A dedicated mapping/quantification audit is the next technical prerequisite; some analog treatment cells have only one sample.','', 'The previously analyzed MG63/HMEC-1 onboard-1g datasets remain useful context but are not new independent validation. Radiation and gravity remain separate targets; exposed and control groups must be matched within tissue/time/experiment.','', '**Recommended next decision:** retain the initial irradiation-associated probe as an exploratory comparator, not a deployed response detector. Prioritize a controlled gravity quantification audit and tissue-matched perturbation data, then test response concepts in the intended muscle/flight domain. An eventual concept-based flight head should expose uncertainty and unassigned evidence. Additional LoRA capacity is not the current demonstrated need.','', '## Numerical correction and provenance','', 'A near-constant TAS1R2 training feature (SD approximately 1e-22) caused extreme expression/PCA logits in an initial pass. The corrected comparison applies a training-only variance filter (variance > 1e-12) before scaling for every fitted model. Earlier outputs were preserved under `history/before-near-zero-variance-fix/`. A regression check confirms perturbing that excluded feature cannot affect predictions. Primary BRIDGE conclusions were unchanged. No variance threshold was selected for better AUROC.','', 'Checks cover input/embedding IDs and hashes, label/column mapping, finite values, whole-file separation, training-only preprocessing, convergence and the variance regression. Two GSE242706 control profiles have contradictory cell-line fields; agreeing titles/cell-type fields were used, and conflicts remain recorded. Pretraining-catalog labels are 122 “unseen” and one absent; this does not prove absence from every version of pretraining.','', 'Key files: `protocol.json`, `input_audit.json`, `label_column_audit.csv`, `manifest.csv`, `metrics.csv`, `specificity.csv`, `predictions.csv`, `controlled_program_expression.csv`, `old_flight_head_stress_response.csv`, `hard_negative_metrics.csv`, `verification.json`, and saved `heads/`.','', 'Sources: [GSE230181](https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE230181), [GSE242706](https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE242706), [GSE222998](https://www.ncbi.nlm.nih.gov/geo/query/acc.cgi?acc=GSE222998). Downloaded SOFT records, expression files and hashes are retained under `sources/`.','', 'All computation is complete. The VM is idle; no new background job or watcher is required.']
    (out/'REPORT.md').write_text('\n'.join(lines)+'\n')
    dump(out/'STATUS.json',{'state':'complete','profiles':123,'encoder_updated':False,'new_radiation_associated_heads_fitted':True,'independent_general_validation':False,'gravity_candidate_status':'Requires transcript/CDS quantification audit','watcher':'paused; no pending job'})
    (out/'README.md').write_text('# Controlled exposure validation\n\n**Complete.** See the [report](REPORT.md), [specificity/transfer figure](specificity_and_transfer.pdf),\n[all-model comparison](exposure_probe_validation.pdf) and [dataset audit](dataset_audit.csv).\n\nThe radiation-associated probe recognizes the within-study contrast but is not sufficiently\nspecific or transferable to assign radiation contributions to flight samples.\n')
    dump(out/'report_provenance.json',{'script_sha256':sha(Path(__file__)),'file_sha256':{p.name:sha(p) for p in out.iterdir() if p.is_file() and p.name!='report_provenance.json'}})
    print('Report, candidate audit, numerical regression check and specificity/transfer figures complete.')

if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);p.add_argument('--folder',type=Path,required=True);a=p.parse_args();run(a.root,a.folder)
